#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <zlib.h>

static unsigned char *read_file(const char *path, size_t *len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    unsigned char *b = malloc((size_t)n + 1);
    if (!b) { fclose(f); return NULL; }
    *len = fread(b, 1, (size_t)n, f); b[*len] = 0; fclose(f); return b;
}

static unsigned char *ascii85_decode(const unsigned char *in, size_t n, size_t *outn) {
    unsigned char *out = malloc(n + 4); size_t oi=0; int count=0; unsigned long tuple=0;
    for (size_t i=0; i<n; i++) {
        unsigned char c=in[i];
        if (isspace(c)) continue;
        if (c=='~') break;
        if (c=='z' && count==0) { out[oi++]=0; out[oi++]=0; out[oi++]=0; out[oi++]=0; continue; }
        if (c<'!' || c>'u') continue;
        tuple = tuple*85 + (unsigned long)(c-'!'); count++;
        if (count==5) {
            out[oi++]=(tuple>>24)&255; out[oi++]=(tuple>>16)&255; out[oi++]=(tuple>>8)&255; out[oi++]=tuple&255;
            tuple=0; count=0;
        }
    }
    if (count>1) {
        for (int j=count; j<5; j++) tuple=tuple*85+84;
        unsigned char tmp[4]={(tuple>>24)&255,(tuple>>16)&255,(tuple>>8)&255,tuple&255};
        for (int j=0;j<count-1;j++) out[oi++]=tmp[j];
    }
    *outn=oi; return out;
}

static unsigned char *inflate_data(const unsigned char *in, size_t n, size_t *outn) {
    uLongf cap = n ? n*8+1024 : 1024;
    for (int tries=0; tries<12; tries++) {
        unsigned char *out=malloc(cap); if (!out) return NULL; uLongf got=cap;
        int r=uncompress(out,&got,in,(uLong)n);
        if (r==Z_OK) { *outn=(size_t)got; return out; }
        free(out);
        if (r==Z_BUF_ERROR) { cap*=4; continue; }
        return NULL;
    }
    return NULL;
}

int main(int argc, char **argv) {
    if (argc<2) return 2;
    size_t len; unsigned char *pdf=read_file(argv[1]); if (!pdf) return 3;
    size_t pos=0, sn=0;
    while (pos<len) {
        unsigned char *s=(unsigned char*)strstr((char*)pdf+pos,"stream");
        if (!s) break;
        size_t sp=(size_t)(s-pdf);
        if (sp>0 && (isalnum(pdf[sp-1]) || pdf[sp-1]=='_')) { pos=sp+6; continue; }
        size_t data=sp+6;
        if (data<len && pdf[data]=='\r') data++;
        if (data<len && pdf[data]=='\n') data++;
        unsigned char *e=(unsigned char*)strstr((char*)pdf+data,"endstream");
        if (!e) break;
        size_t en=(size_t)(e-pdf); while (en>data && (pdf[en-1]=='\n'||pdf[en-1]=='\r')) en--;
        size_t n=en-data; unsigned char *buf=malloc(n+1); memcpy(buf,pdf+data,n); buf[n]=0;
        /* The nearest preceding dictionary determines filters. */
        size_t hs=sp>1200?sp-1200:0; int a85=0, flate=0;
        for (size_t i=hs;i<sp;i++) {
            if (i+15<sp && memcmp(pdf+i,"/ASCII85Decode",14)==0) a85=1;
            if (i+12<sp && memcmp(pdf+i,"/FlateDecode",12)==0) flate=1;
        }
        size_t dn=n; unsigned char *dec=buf;
        if (a85) { dec=ascii85_decode(buf,n,&dn); free(buf); }
        if (flate) { size_t fn; unsigned char *inf=inflate_data(dec,dn,&fn); free(dec); dec=inf; dn=fn; }
        printf("\n--- stream %zu filters=%s%s bytes=%zu ---\n",++sn,a85?"ASCII85 ":"",flate?"Flate":"",dn);
        if (dec) fwrite(dec,1,dn,stdout); else printf("[decode failed]");
        if (dec) free(dec); pos=en+9;
    }
    free(pdf); return 0;
}

